    function isTypingTarget(target){return target&&(/INPUT|TEXTAREA|SELECT/.test(target.tagName)||target.isContentEditable);}
    function installKeyboardControls(){window.addEventListener('keydown',function(event){if(!editorRoot.classList.contains('open')||(activeTab!=='advanced'&&activeTab!=='bulletAdvanced')||isTypingTarget(event.target))return;var key=event.key.toLowerCase();if((key==='delete'||key==='backspace')&&selectedNodes.length){event.preventDefault();deleteSelected();}else if((event.ctrlKey||event.metaKey)&&key==='c'){event.preventDefault();copySelected();}else if((event.ctrlKey||event.metaKey)&&key==='v'){event.preventDefault();pasteNodes();}else if((event.ctrlKey||event.metaKey)&&key==='z'){event.preventDefault();if(event.shiftKey)restoreGraph(redoStack,undoStack);else restoreGraph(undoStack,redoStack);}else if((event.ctrlKey||event.metaKey)&&key==='y'){event.preventDefault();restoreGraph(redoStack,undoStack);}});}

